function blank(){return {gifts:[],plans:[],messages:[],session:null,profile:{name:'Joshua GBAFA',email:'joshua@example.com',phone:'024 000 0000'},prefs:{email:true,whatsapp:false,sms:false,updates:false},theme:'light',simple:false};}
let db;try{db={...blank(),...JSON.parse(localStorage.getItem(key)||'null')}}catch{db=blank()}
let draft= fresh(),step=1,view='home',dashTab='history',lastGift=null,filter='',statusFilter='all',busy=false;
function fresh(){return {country:'GH',phoneCountry:'GH',currency:'GHS',amount:'',kind:'individual',frequency:'once',identity:'new',email:'',name:'',phone:'',org:'',orgType:'Church',role:'Finance Manager',method:'momo',network:'MTN MoMo',day:'1',updates:false,mandate:false,outcome:'received',partner:false};}
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('Browser storage is unavailable. Keep this tab open to retain your progress.')}}
const money=(n,c)=>new Intl.NumberFormat('en',{style:'currency',currency:c,currencyDisplay:'code',maximumFractionDigits:2}).format(Number(n)||0);
function amountPresets(currency){const groups=[
  [['IDR','VND'],[50000,100000,250000,500000,1000000]],
  [['UGX','TZS','RWF','KHR','LAK','GNF','PYG','UZS','MGA','MWK','CDF','BIF'],[10000,25000,50000,100000,250000]],
  [['XOF','XAF'],[5000,10000,25000,50000,100000]],
  [['NGN','JPY','KRW','CLP','ISK','ARS'],[1000,2500,5000,10000,25000]],
  [['KES','ZMW','DZD','AOA','ETB','GMD','MZN','NAD','NPR','PKR','BDT','LKR'],[500,1000,2500,5000,10000]],
  [['ZAR','INR','PHP','THB','MXN','BRL','TRY','EGP','CNY','HKD','TWD'],[100,250,500,1000,2500]],
  [['BHD','KWD','OMR','JOD'],[5,10,25,50,100]]
];return groups.find(([currencies])=>currencies.includes(currency))?.[1]||[10,25,50,100,200]}
function presetButtons(){return amountPresets(draft.currency).map(n=>`<button type="button" data-amount="${n}" class="${Number(draft.amount)===n?'selected':''}">${n.toLocaleString()}</button>`).join('')}
const donationTerms=s=>String(s??'').replace(/\bGifts\b/g,'Donations').replace(/\bgifts\b/g,'donations').replace(/\bGift\b/g,'Donation').replace(/\bgift\b/g,'donation').replace(/\bGIFT-/g,'DONATION-');
const donationRef=id=>String(id??'').replace(/^GIFT-/,'DONATION-');
const countryName=c=>names.of(c), date=s=>new Date(s).toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'}), uid=prefix=>prefix+'-'+crypto.randomUUID().slice(0,8).toUpperCase();
function nextDate(day,offset=1){const d=new Date();d.setMonth(d.getMonth()+offset,Math.min(28,Number(day)||1));return d.toISOString()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
async function copyValue(value,label){let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);copied=true}}catch{}if(!copied){const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();try{document.execCommand('copy')}catch{}area.remove()}toast(`${label} copied`)}
function applyTheme(){document.body.classList.toggle('dark',db.theme==='dark');document.body.classList.toggle('simple',db.simple)}
function go(v){if(location.hash==='#'+v)render();else location.hash=v;}
function start(partner=false){draft=fresh();draft.partner=partner;draft.frequency=partner?'monthly':'once';draft.identity=db.session?'saved':'new';if(db.session)Object.assign(draft,db.profile);step=1;go('give')}
function methods(){let list=[...(local[draft.country]||[])];if(draft.currency==='EUR'&&!list.some(m=>m[0]==='debit'))list.push(['debit','SEPA Direct Debit','Euro bank account']);if(draft.country==='US')return [['apple','Apple Pay','Pay with Apple Pay'],['card','Debit / credit card','Visa · Mastercard · American Express · Discover'],['paypal','PayPal','Pay with your PayPal account'],['debit','ACH bank debit','U.S. bank account']];if(!list.some(m=>m[0]==='card'))list.push(['card','Debit / credit card','Visa · Mastercard · American Express']);if(!['GH','NG','KE','ZA','CI'].includes(draft.country))list.push(['paypal','PayPal','Pay with your PayPal account']);if(['CA','GB','IE','FR','DE','IT','ES','NL','BE','LU','AT','FI','SE','DK','NO','CH','AU','NZ','JP','SG'].includes(draft.country))list.push(['apple','Apple Pay','Pay with Apple Pay']);return list.sort((a,b)=>Number(['bank','wire'].includes(a[0]))-Number(['bank','wire'].includes(b[0])))}
function selectedMethod(){return methods().find(x=>x[0]===draft.method)||methods()[0]}
function methodIcon(method){return ({momo:'◉',wallet:'◈',qr:'▦',bank:'↗',debit:'▤',card:'▰',apple:'●',paypal:'P',local:'⌁',ussd:'⌗',wire:'⇄',crypto:'₿'})[method]||'•'}
function countryCurrencyLabel(code){return `${flag(code)} ${countryName(code)} — ${currencyMap[code]||'USD'}`}
const currencyAliases={cedi:'GH',cedis:'GH','ghana cedi':'GH','ghanaian cedis':'GH',naira:'NG',nairas:'NG','nigerian naira':'NG',rand:'ZA','south african rand':'ZA','kenyan shilling':'KE','ugandan shilling':'UG','tanzanian shilling':'TZ'};
function countrySearchMatch(value){const q=value.trim().toLowerCase();if(!q)return null;const direct=countries.find(c=>q===countryCurrencyLabel(c.code).toLowerCase()||q===c.name.toLowerCase());if(direct)return direct;if(currencyAliases[q])return countries.find(c=>c.code===currencyAliases[q])||null;const matches=countries.filter(c=>{const currency=currencyMap[c.code]||'USD';return q===currency.toLowerCase()||q===currencyNames.of(currency).toLowerCase()});return matches.length===1?matches[0]:null}
function countryPicker(){return `<label class="label" for="country-search">Country & currency</label><div class="country-picker"><input class="field" id="country-search" list="country-options" value="${esc(countryCurrencyLabel(draft.country))}" placeholder="Search country, currency code or currency name" autocomplete="off" onfocus="this.select()"><span aria-hidden="true">⌕</span></div><datalist id="country-options">${countries.map(c=>{const currency=currencyMap[c.code]||'USD',aliases=c.code==='GH'?' · Cedi · Cedis':'';return `<option value="${esc(countryCurrencyLabel(c.code))}">${esc(c.code)} · ${esc(currency)} · ${esc(currencyNames.of(currency))}${aliases}</option>`}).join('')}</datalist><select id="country" name="country" class="country-native" tabindex="-1" aria-hidden="true">${options(countries.map(c=>[c.code,countryCurrencyLabel(c.code)]),draft.country)}</select>`}
function phoneCountryLabel(code,full=false){return full?`${flag(code)} ${countryName(code)} — ${code} ${callingCode[code]||'+'}`:`${flag(code)} ${code} ${callingCode[code]||'+'}`}
function phoneCountrySearchMatch(value){const q=value.trim().toLowerCase();if(!q)return null;const direct=countries.find(c=>[c.code,c.name,phoneCountryLabel(c.code),phoneCountryLabel(c.code,true)].some(v=>q===v.toLowerCase()));if(direct)return direct;const normalized=q.replace(/\s/g,'');const matches=countries.filter(c=>{const dial=callingCode[c.code]||'';return normalized===dial.toLowerCase()||normalized===dial.replace('+','')});return matches.length===1?matches[0]:null}
function processorRoute(method=draft.method,country=draft.country){if(method==='paypal')return 'paypal';if(method==='crypto')return 'bitpay';return ['GH','NG','KE','ZA','CI'].includes(country)?'paystack':'stripe'}
function setCountry(c){draft.country=c;draft.phoneCountry=c;draft.currency=currencyMap[c]||'USD';const m=methods()[0];draft.method=m[0];draft.network=m[3]?.[0]||'';draft.mandate=false}
function isAuto(m=draft.method){return ['card','debit','paypal','apple'].includes(m)}
function field(label,name,value='',type='text',extra=''){return `<label class="label" for="${name}">${label}</label><input class="field" id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}
function phoneField(label,name,value='',editableCountry=false){const code=editableCountry?(draft.phoneCountry||draft.country):draft.country;return `<label class="label" for="${name}">${label}</label><div class="phone-field ${editableCountry?'phone-field-editable':''}">${editableCountry?`<div class="phone-code-picker"><input id="${name}-country" class="field" list="${name}-country-options" value="${esc(phoneCountryLabel(code))}" data-phone-country="true" aria-label="Phone country code" autocomplete="off" onfocus="this.select()"><span aria-hidden="true">⌄</span></div><datalist id="${name}-country-options">${countries.map(c=>`<option value="${esc(phoneCountryLabel(c.code,true))}">${esc(c.code)} · ${esc(callingCode[c.code]||'+')} · ${esc(c.name)}</option>`).join('')}</datalist>`:`<span>${esc(callingCode[code]||'+')}</span>`}<input class="field" id="${name}" name="${name}" type="tel" inputmode="tel" autocomplete="tel-national" value="${esc(value)}" placeholder="Enter the rest of the number"></div>`}
function transferInstructions(){const rows=bankDetails[draft.country]||[['Account name','BENMP Global Giving'],['Bank name','International Receiving Account'],['Account number','0000000000'],['Branch','Global Payments Desk'],['SWIFT / BIC','BENMXX00'],['Currency',draft.currency]];return `<div class="transfer-card"><p class="transfer-title">Bank transfer details</p>${rows.map(([label,value])=>`<div class="transfer-row"><div><small>${esc(label)}</small><strong>${esc(value)}</strong></div><button type="button" class="copy-button" data-copy="${esc(value)}" data-copy-label="${esc(label)}">Copy</button></div>`).join('')}<p class="hint">Use your email or BENMP ID as the payment reference.</p></div>`}
function cardDetails(){return `<div class="brand-row"><span class="card-brand visa">VISA</span><span class="card-brand mastercard" aria-label="Mastercard"><i></i><i></i></span>${draft.country==='US'?'<span class="card-brand amex">AMEX</span><span class="card-brand discover">DISCOVER</span>':''}</div><div class="card-entry">${field('Card number','cardNumber',draft.cardNumber||'','text','inputmode="numeric" autocomplete="cc-number" maxlength="23" placeholder="1234 5678 9012 3456"')}${field('Name on card','cardName',draft.cardName||'','text','autocomplete="cc-name" placeholder="Name as shown on card"')}<div class="grid2"><div>${field('Expiration date','cardExpiry',draft.cardExpiry||'','text','inputmode="numeric" autocomplete="cc-exp" maxlength="7" placeholder="MM / YY"')}</div><div>${field('Security code','cardCvc',draft.cardCvc||'','text','inputmode="numeric" autocomplete="cc-csc" maxlength="4" placeholder="CVC"')}</div></div>${field('Billing postal code','billingPostal',draft.billingPostal||'','text','autocomplete="postal-code" placeholder="Postal code"')}</div>`}
function applePayDetails(){return `<div class="wallet-checkout"><div class="wallet-summary"><span>Apple Pay</span><strong>${esc(money(draft.amount,draft.currency))}</strong></div><button type="button" class="apple-pay-button" data-action="apple-pay"><span aria-hidden="true">●</span> Pay with Apple Pay</button><p class="hint center">Confirm with Face ID, Touch ID or your device passcode.</p></div>`}
function debitDetails(){return `<div class="bank-entry">${field('Account holder name','bankHolder',draft.bankHolder||'','text','autocomplete="name" placeholder="Name on the account"')}${field('Bank name','bankName',draft.bankName||'','text','autocomplete="organization" placeholder="Your bank"')}<div class="grid2"><div>${field(draft.country==='US'?'Routing number':'Sort / routing code','bankCode',draft.bankCode||'','text','inputmode="numeric" placeholder="Bank code"')}</div><div>${field(draft.currency==='EUR'?'IBAN':'Account number','bankAccount',draft.bankAccount||'','text','inputmode="numeric" placeholder="Account number"')}</div></div><p class="hint">Your bank may ask you to approve this payment.</p></div>`}
function options(arr,value){return arr.map(x=>{const v=typeof x==='string'?x:x[0],t=typeof x==='string'?x:x[1];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}
function select(label,name,arr,value){return `<label class="label" for="${name}">${label}</label><select class="field" id="${name}" name="${name}">${options(arr,value)}</select>`}
function seg(name,arr,value){return `<div class="segmented" role="group" aria-label="${name}">${arr.map(([v,l])=>`<button type="button" data-set="${name}" data-value="${v}" aria-pressed="${value===v}" class="${value===v?'selected':''}">${l}</button>`).join('')}</div>`}
function button(label,action,cl='primary',extra=''){return `<button type="button" class="${cl}" data-action="${action}" ${extra}>${label}</button>`}
function header(){document.querySelectorAll('[data-auth-only]').forEach(el=>el.hidden=!db.session);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+view||(a.hash==='#give'&&view==='home')));$('#signin').textContent=db.session?'Joshua GBAFA':'Sign in';$('#unread').textContent=db.session?(db.messages.filter(m=>!m.read).length||''):'';const appearance=$('#appearance');appearance.title=db.theme==='dark'?'Switch to light mode':'Switch to dark mode';appearance.onclick=e=>{e.stopPropagation();db.theme=db.theme==='dark'?'light':'dark';save();applyTheme();appearance.title=db.theme==='dark'?'Switch to light mode':'Switch to dark mode'};applyTheme()}
function shell(content){main.innerHTML=`<div class="page">${content}</div>`;header()}
function home(){shell(`<section class="hero hero-cinematic"><div class="hero-media" aria-hidden="true"><img src="assets/bangui-mega-hero.gif" alt=""></div><div class="hero-content"><div class="eyebrow">HOW CAN THEY HEAR WITHOUT A PREACHER?</div><h1>Bring<br><span>Salvation</span><br>To The Multitudes</h1><div class="hero-actions">${button('Give','start','primary')}${button('Become a BENMP partner','partner','secondary')}</div><p class="hint">Already a partner? <button class="text-link" data-action="login">Sign in</button></p></div></section>`)}
function summary(){return `<aside class="panel summary"><p class="eyebrow">YOUR PARTNERSHIP</p><div class="sum-amount"><span>${draft.currency}</span> <b id="summary-amount">${draft.amount?Number(draft.amount).toLocaleString('en',{maximumFractionDigits:2}):'—'}</b></div><p class="muted">${draft.frequency==='monthly'?'A monthly commitment':'A one-time donation'}</p><hr class="divider"><dl><dt>Giving as</dt><dd>${draft.kind==='individual'?'Individual':'Organization'}</dd><dt>Country</dt><dd>${flag(draft.country)} ${esc(countryName(draft.country))}</dd><dt>Frequency</dt><dd>${draft.frequency==='monthly'?'Monthly':'One time'}</dd>${step===3?`<dt>Method</dt><dd>${esc(selectedMethod()[1])}</dd>`:''}</dl><div class="summary-bottom"><strong>Payment options in ${esc(countryName(draft.country))}</strong><div class="method-lines">${methods().map(m=>`<div class="method-line"><span>${esc(m[1])}</span>${m[3]?.length?`<small>${esc(m[3].join(' · '))}</small>`:`<small>${esc(m[2])}</small>`}</div>`).join('')}</div></div></aside>`}
function giving(){if(!methods().some(m=>m[0]===draft.method))draft.method=methods()[0][0];const labels=draft.partner?['Your details','Monthly pledge','Payment']:['Your donation','Your details','Payment'],headings=draft.partner?['Become a BENMP Partner','Your monthly pledge','Choose how to pay']:[step===1?'Give your donation':'',step===2?'Your details':'','Choose how to pay'],titles=draft.partner?['Create your partner profile','Set your monthly pledge','Payment method']:['','Let’s make it personal','Payment method'],taglines=draft.partner?['Register once, then choose your monthly partnership.','Choose what you expect to give each month.','Make your first donation and start your monthly partnership.']:['','Your email is your BENMP ID.','Choose the way that works for you.'],body=draft.partner?(step===1?partnerDetailsUI():step===2?partnerPledgeUI():paymentUI()):(step===1?amountUI():step===2?detailsUI():paymentUI());shell(`<div class="intro"><div>${draft.partner?'<div class="eyebrow">BECOME A BENMP PARTNER</div>':step===1?'':'<div class="eyebrow">THE BENMP PARTNERSHIP</div>'}<h1>${headings[step-1]}</h1>${taglines[step-1]?`<p class="tagline">${taglines[step-1]}</p>`:''}</div><div class="steps">${labels.map((label,i)=>`<button class="step ${step===i+1?'current':step>i+1?'complete':''}" data-step="${i+1}" ${i+1>step?'disabled':''}><span>${step>i+1?'✓':i+1}</span>${label}</button>`).join('')}</div></div><div class="giving-layout"><section class="panel">${titles[step-1]?`<div class="section-title"><h2>${titles[step-1]}</h2></div>`:''}<form id="giving-form" novalidate>${body}<div id="form-error" role="alert"></div><div class="actions">${step>1?button('Back','back','secondary'):''}<button class="primary" type="submit">${step<3?'Continue':draft.frequency==='monthly'?(isAuto()?'Start monthly giving':'Give & set monthly reminder'):'Give '+esc(money(draft.amount,draft.currency))}</button></div><p class="hint center">${step===3?'Your payment details are protected.':draft.partner&&step===1?'Your email becomes your BENMP ID.':draft.partner?'Your first donation is made when you continue through payment.':step===2?'No password to remember.':'Any amount, from wherever you are.'}</p></form></section>${summary()}</div>`)}

function amountUI(){return `${seg('kind',[['individual','Individual'],['organization','Organization']],draft.kind)}${countryPicker()}<div style="margin-top:24px">${seg('frequency',[['once','One time'],['monthly','Monthly']],draft.frequency)}</div><label class="label" for="amount">Choose any amount</label><div class="amount-box"><span>${draft.currency}</span><input id="amount" name="amount" inputmode="decimal" aria-label="Donation amount" value="${esc(draft.amount)}" placeholder="Enter amount" autocomplete="off"></div><div class="presets">${presetButtons()}</div>${draft.frequency==='monthly'?select('Monthly date (after your first donation today)','day',Array.from({length:28},(_,i)=>[String(i+1),'Day '+(i+1)]),draft.day):''}<p class="hint">${draft.frequency==='once'?`Prefer an ongoing commitment? <button type="button" class="text-link" data-action="partner-current">Become a BENMP partner</button>`:'First donation today. Then each month until you pause or cancel.'}</p>`}
function choice(id,title,description,body,on,action){return `<div class="choice ${on?'on':''}"><button class="choice-head" type="button" data-${action}="${id}" aria-expanded="${on}"><span class="radio" aria-hidden="true"></span><span><strong>${title}</strong><small>${description}</small></span><span class="chevron">${on?'⌃':'⌄'}</span></button>${on?`<div class="choice-body">${body}</div>`:''}</div>`}
function organizationDetails(){return `<hr class="divider"><h3>Organization details</h3>${field('Organization name','org',draft.org,'text','placeholder="Grace Outreach Church"')}${select('Organization type','orgType',['Church','Ministry','Company','Foundation','Other'],draft.orgType)}${select('Your role','role',['Owner / Admin','Finance Manager','Approver','Representative'],draft.role)}`}
function partnerDetailsUI(){const identity=db.session?`<div class="notice"><strong>Welcome, ${esc(db.profile.name)}</strong><br>Your saved BENMP identity will be used for this partnership.<br>BENMP ID: ${esc(db.profile.email)}</div>`:`${field('Full name','name',draft.name,'text','autocomplete="name" placeholder="Your full name"')}${field('Email / BENMP ID','email',draft.email,'email','autocomplete="email" placeholder="you@example.com"')}${phoneField('Phone / WhatsApp','phone',draft.phone,true)}`;return `${seg('kind',[['individual','Individual'],['organization','Organization']],draft.kind)}${countryPicker()}${identity}${draft.kind==='organization'?organizationDetails():''}<label class="check"><input type="checkbox" name="updates" ${draft.updates?'checked':''}>Send me occasional BENMP ministry updates. Optional.</label>`}
function partnerPledgeUI(){return `<p class="muted">How much would you like to give every month?</p><div class="amount-box"><span>${draft.currency}</span><input id="amount" name="amount" inputmode="decimal" aria-label="Monthly pledge amount" value="${esc(draft.amount)}" placeholder="Enter amount" autocomplete="off"></div><div class="presets">${presetButtons()}</div>${select('Monthly date (after your first donation today)','day',Array.from({length:28},(_,i)=>[String(i+1),'Day '+(i+1)]),draft.day)}<div class="notice"><strong>Your partnership starts today</strong><br>Your first donation is made at checkout. Future donations follow the monthly date you choose.</div><label class="check"><input type="checkbox" name="partnerConfirm" ${draft.partnerConfirm?'checked':''}>Yes, I want to give this amount every month.</label>`}
function detailsUI(){const updates=`<label class="check"><input type="checkbox" name="updates" ${draft.updates?'checked':''}>Send me occasional BENMP ministry updates. Optional.</label>`;if(db.session)return `<div class="notice"><strong>Welcome, ${esc(db.profile.name)}</strong><br>Your saved BENMP details will be used for this donation.<br>BENMP ID: ${esc(db.profile.email)}</div>${draft.kind==='organization'?organizationDetails():''}${updates}`;const saved=`<p class="hint">Sign in securely with your BENMP ID.</p>${button('Sign in','login','secondary')}`;return `${choice('saved','Sign in','Already a partner? Pick up where you left off.',saved,draft.identity==='saved','identity')}${choice('id','Use my BENMP ID','Give again without signing in.',field('BENMP ID (your email)','email',draft.email,'email','placeholder="you@example.com"')+'<p class="hint">This identifies the donation without showing saved account details.</p>',draft.identity==='id','identity')}${choice('new','I’m giving for the first time','A few details to connect your donation.',field('Full name','name',draft.name,'text','autocomplete="name" placeholder="Your full name"')+field('Email / BENMP ID','email',draft.email,'email','autocomplete="email" placeholder="you@example.com"')+phoneField('Phone / WhatsApp','phone',draft.phone,true),draft.identity==='new','identity')}${draft.kind==='organization'?organizationDetails():''}${updates}`}

function methodBody(m){if(m[0]==='momo'||m[0]==='wallet'||m[0]==='qr')return `<label class="label">Choose ${m[0]==='momo'?'your network':'an option'}</label><div class="network">${(m[3]||[]).map(n=>`<button type="button" data-network="${n}" class="${draft.network===n?'selected':''}">${n}</button>`).join('')}</div>${m[0]==='qr'?'<div class="qr-checkout"><div class="qr-code" aria-label="Payment QR code">BENMP<br>PAY</div><p>Scan with your banking app to approve the payment.</p></div>':phoneField('Mobile number','paymentPhone',draft.paymentPhone||draft.phone)}<p class="hint">You will approve the payment on your phone.</p>`;if(m[0]==='card')return cardDetails();if(m[0]==='apple')return applePayDetails();if(m[0]==='paypal')return `<div class="wallet-checkout paypal-checkout"><div class="wallet-summary"><span>PayPal</span><strong>${esc(money(draft.amount,draft.currency))}</strong></div><p>Continue securely with your PayPal account.</p></div>`;if(m[0]==='debit')return debitDetails();if(m[0]==='bank'||m[0]==='wire')return transferInstructions();if(m[0]==='crypto')return `${select('Cryptocurrency','coin',['Bitcoin (BTC)','Ethereum (ETH)','USDC'],draft.coin||'Bitcoin (BTC)')}<p class="hint">Choose your cryptocurrency and continue to payment.</p>`;return `<div class="wallet-checkout"><div class="wallet-summary"><span>${esc(m[1])}</span><strong>${esc(money(draft.amount,draft.currency))}</strong></div><p>Continue to approve this payment.</p></div>`}
function paymentUI(){return `<p class="muted small">${esc(countryCurrencyLabel(draft.country))} · Select a payment method</p>${methods().map(m=>choice(m[0],m[1],m[2],methodBody(m),draft.method===m[0],'method')).join('')}${draft.frequency==='monthly'?`<div class="notice"><strong>${isAuto()?'Automatic monthly giving':'Monthly reminder'}</strong><br>${isAuto()?`Today: ${esc(money(draft.amount,draft.currency))}. Then on day ${draft.day} of each month until canceled.`:'This method needs a fresh approval each month. We’ll prepare a reminder; it will not be automatically debited.'}</div><label class="check"><input type="checkbox" name="mandate" ${draft.mandate?'checked':''}>${isAuto()?'I agree to this monthly giving schedule.':'Set up a monthly reminder for this commitment.'}</label>`:''}`}
function capture(){const f=$('#giving-form');if(!f)return;for(const el of f.elements){if(!el.name)continue;draft[el.name]=el.type==='checkbox'?el.checked:el.value}}
function identityError(){if(draft.identity==='saved'&&!db.session)return 'Try sign-in, or choose another way to identify your donation.';if(draft.identity!=='saved'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.email))return 'Enter an email address such as joshua@example.com.';if(draft.identity==='new'&&(!draft.name.trim()||!draft.phone.trim()))return 'Add your name and phone number to continue.';return ''}
function organizationError(){if(draft.kind==='organization'&&!draft.org.trim())return 'Add your organization’s name to continue.';return ''}
function validate(){if(draft.partner){if(step===1){if(!db.session){const issue=identityError();if(issue)return issue}const issue=organizationError();if(issue)return issue}if(step===2){const n=Number(draft.amount);if(!Number.isFinite(n)||n<=0)return 'Enter any monthly amount greater than zero.';if(!draft.partnerConfirm)return 'Confirm that you want to give this amount every month.'}}else{if(step===1){const n=Number(draft.amount);if(!Number.isFinite(n)||n<=0)return 'Enter any amount greater than zero.'}if(step===2){const issue=identityError()||organizationError();if(issue)return issue}}if(step===3){if(['momo','wallet'].includes(draft.method)&&!(draft.paymentPhone||draft.phone||'').trim())return 'Enter your mobile number.';if(draft.frequency==='monthly'&&!draft.mandate)return 'Confirm the monthly schedule to continue.'}return ''}

function message(subject,body,channel='Email',extra={}){db.messages.unshift({id:uid('MSG'),subject,body,channel,date:new Date().toISOString(),read:false,...extra})}
function emitNotice(subject,body){message(subject,body);if(db.prefs.whatsapp)message(subject,body,'WhatsApp');if(db.prefs.sms)message(subject,body,'SMS')}
function completeGift(){if(busy)return;busy=true;draft.outcome='received';const now=new Date().toISOString(),identityEmail=draft.identity==='saved'?db.profile.email:draft.email,g={id:uid('DONATION'),amount:Number(draft.amount),currency:draft.currency,country:draft.country,kind:draft.kind,name:draft.identity==='saved'?db.profile.name:draft.name||'Returning partner',email:identityEmail,org:draft.org,reference:draft.reference,method:selectedMethod()[1],methodId:draft.method,processorRoute:processorRoute(),frequency:draft.frequency,status:'received',date:now};db.gifts.unshift(g);lastGift=g.id;if(draft.frequency==='monthly'){const p={id:uid('PLAN'),gift:g.id,amount:g.amount,currency:g.currency,country:g.country,name:g.name,email:g.email,org:g.org,kind:g.kind,method:g.method,methodId:g.methodId,day:Number(draft.day),next:nextDate(draft.day),status:'Active',mode:isAuto()?'Automatic':'Reminder',created:now};db.plans.unshift(p);g.plan=p.id;emitNotice('Your monthly partnership',`${money(p.amount,p.currency)} ${p.mode==='Automatic'?'monthly giving':'monthly reminder'} set up${p.org?' for '+p.org:''}. Next date: ${date(p.next)}. Manage or cancel in My giving.`)}if(draft.partner||draft.identity==='new')message('Welcome to BENMP',`Welcome, ${g.org||g.name}. Your BENMP ID is ${g.email}. Thank you for partnering with us.`, 'Email');emitNotice('Thank you for your donation',`We received your ${money(g.amount,g.currency)} donation. Reference ${g.id}. Thank you for partnering with BENMP.`);db.prefs.updates=draft.updates;save();busy=false;go('result')}
function result(){const g=db.gifts.find(x=>x.id===lastGift)||db.gifts[0];if(!g){go('give');return}const state=g.status==='received'?'success':g.status==='pending'?'pending':'failed';shell(`<section class="panel result"><div class="success-mark status-${state}">${g.status==='received'?'✓':g.status==='pending'?'◷':'!'}</div><div class="eyebrow">${g.status==='received'?'THANK YOU FOR PARTNERING':'YOUR DONATION'}</div><h1>${g.status==='received'?'Your generosity moves us.':g.status==='pending'?'Awaiting confirmation.':'Let’s try that again.'}</h1><p class="muted" style="margin-top:17px">${g.status==='received'?`Thank you, ${esc(g.org||g.name)}. Your donation has been received.`:g.status==='pending'?'Your donation is awaiting confirmation. We’ll notify you as soon as it is complete.':'Your payment was not completed. You can retry without entering your details again.'}</p><div class="receipt-details">${[['Donation',money(g.amount,g.currency)],['Status',g.status==='received'?'Successful':g.status[0].toUpperCase()+g.status.slice(1)],['BENMP ID',g.email],['Payment method',g.method],['Reference',donationRef(g.id)],['Date',date(g.date)]].map(([k,v])=>`<div class="rowline"><span class="muted">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="actions">${g.status==='received'?button('Download receipt','receipt','primary',`data-id="${g.id}"`):g.status==='pending'?button('Confirm payment','confirm-gift','primary',`data-id="${g.id}"`):button('Try again','retry','primary',`data-id="${g.id}"`)}${button('My giving','dashboard','secondary')}${button('Give again','start','secondary')}</div><p class="hint">Your receipt is ready for your records.</p></section>`)}
function totals(){const t={};db.gifts.filter(g=>g.status==='received').forEach(g=>t[g.currency]=(t[g.currency]||0)+g.amount);return Object.entries(t)}
function dashboard(){const received=db.gifts.filter(g=>g.status==='received'),total=totals();shell(`<div class="intro"><div><div class="eyebrow">MY BENMP</div><h1>${db.session?'Welcome, Joshua GBAFA':'Your giving'}</h1><p class="tagline">${db.session?'Your partnership, in one place.':'Sign in to view your partner details.'}</p></div>${button('Give again','start','primary')}</div><div class="stats"><section class="panel stat"><p class="small muted">Confirmed donations</p><strong>${received.length}</strong></section><section class="panel stat"><p class="small muted">Active monthly commitments</p><strong>${db.plans.filter(p=>p.status==='Active').length}</strong></section><section class="panel stat"><p class="small muted">Received · separate currencies</p><strong style="font-size:${total.length>1?'20':'29'}px">${total.length?total.map(([c,n])=>esc(money(n,c))).join('<br>'):'No donations yet'}</strong></section></div><div class="tabs" role="group" aria-label="Giving views">${[['history','Giving history'],['plans','Monthly plans'],['profile','My details'],['overview','Worldwide overview']].map(([id,t])=>`<button data-tab="${id}" class="${dashTab===id?'selected':''}">${t}</button>`).join('')}</div>${dashTab==='history'?historyUI():dashTab==='plans'?plansUI():dashTab==='profile'?profileUI():overviewUI()}`)}
function giftRows(list){return list.length?list.map(g=>`<article class="list-item"><div><div class="item-title">${esc(g.org||g.name)}</div><p>${date(g.date)} · ${esc(g.method)} · ${flag(g.country)} ${esc(countryName(g.country))}</p><p>${esc(donationRef(g.id))} ${g.frequency==='monthly'?'· Monthly':''}</p><div class="message-actions">${g.status==='received'?button('Receipt','receipt','text-link',`data-id="${g.id}"`):g.status==='pending'?button('Confirm payment','confirm-gift','text-link',`data-id="${g.id}"`):button('Retry donation','retry','text-link',`data-id="${g.id}"`)}</div></div><div class="right"><strong>${esc(money(g.amount,g.currency))}</strong><span class="badge ${g.status==='received'?'success':g.status}">${g.status==='received'?'Successful':g.status==='pending'?'Pending':'Failed'}</span></div></article>`).join(''):`<div class="empty"><h3>${db.gifts.length?'No matching donations':'Your story starts with a donation'}</h3><p>${db.gifts.length?'Try another search or status.':'Your donations and receipts will appear here.'}</p>${button('Give','start','primary')}</div>`}
function statementUI(){const email=db.profile.email||db.gifts.find(g=>g.email)?.email||'';return `<section class="panel statement-panel"><div class="section-title"><div><h2>Giving statement</h2><p class="small muted">Create a comprehensive PDF for the period you choose.</p></div><span class="statement-icon" aria-hidden="true">▤</span></div><form id="statement-form"><div class="statement-grid">${select('Timeframe','statement-period',[['this-year','This year'],['30-days','Last 30 days'],['90-days','Last 90 days'],['previous-year','Previous year'],['all','All time']],'this-year')}${field('Email the statement to','statement-email',email,'email','required placeholder="you@example.com"')}</div><div class="actions"><button class="secondary" type="submit" name="statementAction" value="download">Download PDF</button><button class="primary" type="submit" name="statementAction" value="email">Email PDF</button></div></form></section>`}
function historyUI(){let list=db.gifts.filter(g=>(statusFilter==='all'||g.status===statusFilter)&&[g.id,g.name,g.org,g.email,g.method].join(' ').toLowerCase().includes(filter.toLowerCase()));return `${statementUI()}<section class="panel"><div class="section-title"><h2>Giving history</h2>${button('Export CSV','export','text-link')}</div><div class="filters"><input id="history-search" class="field" placeholder="Search donations, people or references" aria-label="Search giving history" value="${esc(filter)}"><select id="status-filter" class="field" aria-label="Filter by status">${options([['all','All statuses'],['received','Received'],['pending','Pending'],['failed','Failed']],statusFilter)}</select></div><div id="gift-list">${giftRows(list)}</div></section>`}

function plansUI(){return `<section class="panel"><div class="section-title"><h2>Monthly partnerships</h2>${button('New monthly plan','partner','text-link')}</div><p class="small muted">Changes apply to future installments. Paused months are never back-charged.</p>${db.plans.length?db.plans.map(p=>`<article class="plan"><div class="section-title"><div><h3>${esc(money(p.amount,p.currency))} / month</h3><p class="small muted">${esc(p.org||p.name)} · ${esc(p.method)}</p></div><span class="badge ${p.status==='Active'?'success':''}">${p.status}</span></div><div class="rowline"><span class="muted">Collection</span><span>${p.mode==='Automatic'?'Automatic monthly giving':'Monthly reminder — approve each donation'}</span></div><div class="rowline"><span class="muted">Next ${p.mode==='Automatic'?'payment':'reminder'}</span><span>${p.status==='Canceled'?'—':date(p.next)}</span></div><div class="actions">${p.status!=='Canceled'?button('Edit plan','edit-plan','secondary',`data-id="${p.id}"`):''}${p.status==='Active'?button('Pause','pause-plan','secondary',`data-id="${p.id}"`):p.status==='Paused'?button('Resume','resume-plan','secondary',`data-id="${p.id}"`):''}${p.status==='Active'?button(p.mode==='Automatic'?'Process next payment':'Send reminder','run-plan','secondary',`data-id="${p.id}"`):''}${p.status!=='Canceled'?button('Cancel','cancel-plan','text-link',`data-id="${p.id}"`):''}</div></article>`).join(''):`<div class="empty"><h3>Build a lasting partnership</h3><p>Choose an amount and schedule that works for you.</p>${button('Become a BENMP partner','partner','primary')}</div>`}</section>`}
function profileUI(){return `<section class="panel preferences"><h2>${db.session?'Your saved details':'Your partner account'}</h2>${db.session?`<form id="profile-form">${field('Name','profile-name',db.profile.name)}${field('Email / BENMP ID','profile-email',db.profile.email,'email')}${field('Phone / WhatsApp','profile-phone',db.profile.phone,'tel')}<div class="actions"><button type="submit" class="primary">Save details</button>${button('Sign out','logout','secondary')}</div></form>`:`<p class="muted" style="margin:18px 0">Sign in with your BENMP ID to view your saved details.</p>${button('Sign in','login','primary')}`}</section>`}
function overviewUI(){const map={};db.gifts.filter(g=>g.status==='received').forEach(g=>{const k=g.country+'|'+g.currency;map[k]=(map[k]||0)+g.amount});const people=new Map();db.gifts.filter(g=>g.status==='received').forEach(g=>{const k=g.kind+'|'+g.email;if(!people.has(k))people.set(k,new Set());people.get(k).add(g.date.slice(0,7))});return `<section class="panel"><div class="section-title"><h2>Worldwide overview</h2></div><p class="muted small">Confirmed donation totals by country. Currencies remain separate.</p><div class="grid2" style="margin:24px 0"><div class="notice"><strong>${people.size} partners</strong><br>Individuals and organizations counted separately.</div><div class="notice"><strong>${[...people.values()].filter(s=>s.size>=2).length} repeat givers</strong><br>Confirmed donations in at least two calendar months.</div></div>${Object.keys(map).length?Object.entries(map).map(([k,n])=>{const [c,cur]=k.split('|');return `<div class="list-item"><h3>${flag(c)} ${esc(countryName(c))}</h3><strong>${esc(money(n,cur))}</strong></div>`}).join(''):'<div class="empty"><p>No confirmed donations yet.</p></div>'}</section>`}
function messagesUI(){shell(`<div class="intro"><div><div class="eyebrow">STAY CONNECTED</div><h1>Messages</h1><p class="tagline">Your email, WhatsApp, SMS and in-app messages in one place.</p></div>${button('Notification preferences','preferences','secondary')}</div><section class="panel"><div class="section-title"><h2>Inbox</h2>${button('Mark all read','read-all','text-link')}</div><p class="small muted">Your latest BENMP messages and statements.</p>${db.messages.length?db.messages.map(m=>`<article class="message ${m.read?'':'unread'}"><div class="meta"><span class="badge">${esc(m.channel)}</span><span class="small muted">${date(m.date)}</span></div><h3>${esc(donationTerms(m.subject))}</h3><p>${esc(donationTerms(m.body))}</p>${m.attachment?`<div class="attachment"><span>▤ ${esc(m.attachment)}</span>${button('Download PDF','statement-attachment','text-link',`data-period="${esc(m.statementPeriod||'all')}"`)}</div>`:''}<div class="message-actions">${!m.read?button('Mark read','read-message','text-link',`data-id="${m.id}"`):'<span class="small muted">Read</span>'}${button('Reply','reply','text-link',`data-id="${m.id}"`)}</div></article>`).join(''):`<div class="empty"><h3>Your inbox is ready</h3><p>Your BENMP messages and statements will appear here.</p></div>`}<div class="actions">${button('Compose message','compose','secondary')}</div></section>`)}
function modal(title,body){$('#modal-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close()}
function login(){modal('Sign in to BENMP',`<p>No password to remember. Enter your email or BENMP ID and we’ll send you a secure sign-in link.</p><form id="login-form">${field('Email / BENMP ID','login-entry','','text','placeholder="joshua@example.com" required autocomplete="off"')}<button class="primary full" type="submit">Continue with sign-in link</button><p class="hint">Your sign-in link is private and expires after use.</p></form>`)}
function finishLogin(entry){db.session={entry,date:new Date().toISOString()};db.profile.name='Joshua GBAFA';draft.identity='saved';Object.assign(draft,{name:db.profile.name,email:db.profile.email,phone:db.profile.phone});message('Welcome, Joshua GBAFA','You have signed in to BENMP. Your saved details are ready for your next donation.','In-app');save();close();toast('Welcome, Joshua GBAFA');if(view==='give')render();else go('dashboard')}
function preferences(){modal('How would you like to hear from us?',`<form id="prefs-form"><p>Choose how BENMP may contact you. Essential donation messages remain available in your inbox.</p>${[['email','Email receipts and account messages'],['whatsapp','WhatsApp notifications'],['sms','SMS notifications'],['updates','Occasional ministry updates']].map(([k,l])=>`<label class="check"><input type="checkbox" name="${k}" ${db.prefs[k]?'checked':''}>${l}</label>`).join('')}<button class="primary full" type="submit">Save preferences</button></form>`)}
function loadReceiptLogo(){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src='assets/healing-jesus.png'})}
function jpegPDF(jpeg,width,height){const enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const push=value=>{const bytes=typeof value==='string'?enc.encode(value):value;parts.push(bytes);length+=bytes.length},object=(number,body,binary)=>{offsets[number]=length;push(`${number} 0 obj\n${body}`);if(binary){push('\nstream\n');push(binary);push('\nendstream')}push('\nendobj\n')};push('%PDF-1.4\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');object(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im1 5 0 R >> >> /Contents 4 0 R >>');const content=enc.encode('q\n595 0 0 842 0 0 cm\n/Im1 Do\nQ\n');object(4,`<< /Length ${content.length} >>`,content);object(5,`<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>`,jpeg);const xref=length;push(`xref\n0 6\n0000000000 65535 f \n`);for(let i=1;i<=5;i++)push(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
async function receiptPDF(g){const logo=await loadReceiptLogo(),canvas=document.createElement('canvas'),width=1240,height=1754;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d'),ink='#172436',muted='#64748b',orange='#ef8a22',line='#dfe6ee',partner=g.org||g.name,receiptAmount=`${g.currency} ${Number(g.amount).toLocaleString('en',{maximumFractionDigits:2})}`,rows=[['Receipt number',donationRef(g.id)],['Date issued',date(g.date)],['Donation status','Confirmed'],['Partner',partner],['BENMP ID',g.email],['Donation amount',receiptAmount],['Country',countryName(g.country)],['Payment method',g.method],['Frequency',g.frequency==='monthly'?'Monthly partnership':'One-time donation']];ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.strokeStyle='rgba(239,138,34,.34)';ctx.lineWidth=4;ctx.strokeRect(52,52,width-104,height-104);ctx.fillStyle=orange;ctx.fillRect(52,52,width-104,9);ctx.drawImage(logo,78,82,120,90);ctx.fillStyle=ink;ctx.font='700 54px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('BENMP',220,128);ctx.fillStyle=muted;ctx.font='600 17px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('GLOBAL GIVING PLATFORM',222,158);ctx.textAlign='right';ctx.fillStyle=orange;ctx.font='700 18px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('DONATION RECEIPT',1162,118);ctx.fillStyle=muted;ctx.font='500 16px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(donationRef(g.id),1162,148);ctx.textAlign='left';ctx.fillStyle=ink;ctx.font='700 43px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('Thank you for your partnership.',78,256);ctx.fillStyle=muted;ctx.font='400 22px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(`We received your ${receiptAmount} donation. Keep this receipt for your records.`,78,296);ctx.fillStyle='rgba(239,138,34,.09)';ctx.fillRect(78,342,1084,112);ctx.fillStyle=orange;ctx.fillRect(78,342,7,112);ctx.fillStyle=ink;ctx.font='700 20px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('CONFIRMED DONATION',110,386);ctx.fillStyle=muted;ctx.font='400 18px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('Your donation has been recorded by BENMP.',110,420);let y=520;for(const [label,value] of rows){ctx.fillStyle=muted;ctx.font='600 16px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(label.toUpperCase(),78,y);ctx.fillStyle=ink;ctx.font='500 22px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(String(value),480,y);ctx.strokeStyle=line;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(78,y+27);ctx.lineTo(1162,y+27);ctx.stroke();y+=92}ctx.fillStyle=orange;ctx.fillRect(78,1450,1084,4);ctx.fillStyle=ink;ctx.font='700 24px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('BENMP Global Giving Platform',78,1504);ctx.fillStyle=muted;ctx.font='400 16px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('Keep this receipt for your records.',78,1540);ctx.fillText('For questions about this donation, contact your BENMP representative.',78,1570);ctx.fillText(`Reference: ${donationRef(g.id)}`,78,1618);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.92));return jpegPDF(new Uint8Array(await blob.arrayBuffer()),width,height)}
function statementWindow(period){const now=new Date(),end=new Date(now),start=new Date(0);let label='All time';if(period==='all')end.setTime(8640000000000000);else if(period==='this-year'){start.setFullYear(now.getFullYear(),0,1);start.setHours(0,0,0,0);label=`1 Jan ${now.getFullYear()} – ${date(end)}`}else if(period==='30-days'){start.setTime(now.getTime()-29*86400000);start.setHours(0,0,0,0);label=`${date(start)} – ${date(end)}`}else if(period==='90-days'){start.setTime(now.getTime()-89*86400000);start.setHours(0,0,0,0);label=`${date(start)} – ${date(end)}`}else if(period==='previous-year'){start.setFullYear(now.getFullYear()-1,0,1);start.setHours(0,0,0,0);end.setFullYear(now.getFullYear()-1,11,31);end.setHours(23,59,59,999);label=`1 Jan ${now.getFullYear()-1} – 31 Dec ${now.getFullYear()-1}`}return {start,end,label}}
function statementRows(period){const range=statementWindow(period);return {range,rows:db.gifts.filter(g=>{const d=new Date(g.date);return d>=range.start&&d<=range.end}).sort((a,b)=>new Date(b.date)-new Date(a.date))}}
function jpegPagesPDF(jpegs,width,height){const enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const push=value=>{const bytes=typeof value==='string'?enc.encode(value):value;parts.push(bytes);length+=bytes.length},object=(number,body,binary)=>{offsets[number]=length;push(`${number} 0 obj\n${body}`);if(binary){push('\nstream\n');push(binary);push('\nendstream')}push('\nendobj\n')},pageIds=jpegs.map((_,i)=>3+i*3),size=3+jpegs.length*3;push('%PDF-1.4\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,`<< /Type /Pages /Kids [${pageIds.map(id=>id+' 0 R').join(' ')}] /Count ${jpegs.length} >>`);jpegs.forEach((jpeg,i)=>{const page=pageIds[i],content=page+1,image=page+2,stream=enc.encode(`q\n595 0 0 842 0 0 cm\n/Im${i+1} Do\nQ\n`);object(page,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im${i+1} ${image} 0 R >> >> /Contents ${content} 0 R >>`);object(content,`<< /Length ${stream.length} >>`,stream);object(image,`<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>`,jpeg)});const xref=length;push(`xref\n0 ${size}\n0000000000 65535 f \n`);for(let i=1;i<size;i++)push(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size ${size} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
async function statementPDF(period){const logo=await loadReceiptLogo(),{range,rows}=statementRows(period),width=1240,height=1754,perPage=12,pageCount=Math.max(1,Math.ceil(rows.length/perPage)),images=[],confirmed=rows.filter(g=>g.status==='received'),totals={};confirmed.forEach(g=>totals[g.currency]=(totals[g.currency]||0)+Number(g.amount));for(let pageIndex=0;pageIndex<pageCount;pageIndex++){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d'),ink='#172436',muted='#64748b',orange='#ef8a22',line='#dfe6ee';ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.strokeStyle='rgba(239,138,34,.34)';ctx.lineWidth=4;ctx.strokeRect(52,52,width-104,height-104);ctx.fillStyle=orange;ctx.fillRect(52,52,width-104,9);ctx.drawImage(logo,78,82,120,90);ctx.fillStyle=ink;ctx.font='700 54px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('BENMP',220,128);ctx.fillStyle=muted;ctx.font='600 17px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('GLOBAL GIVING PLATFORM',222,158);ctx.textAlign='right';ctx.fillStyle=orange;ctx.font='700 18px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('GIVING STATEMENT',1162,118);ctx.fillStyle=muted;ctx.font='500 16px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(`PAGE ${pageIndex+1} OF ${pageCount}`,1162,148);ctx.textAlign='left';let y=236;if(pageIndex===0){ctx.fillStyle=ink;ctx.font='700 38px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(db.profile.name||rows[0]?.name||'BENMP Partner',78,y);ctx.fillStyle=muted;ctx.font='400 20px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(db.profile.email||rows[0]?.email||'',78,y+38);ctx.fillText(`Statement period: ${range.label}`,78,y+78);ctx.fillStyle='rgba(239,138,34,.09)';ctx.fillRect(78,y+116,1084,118);ctx.fillStyle=orange;ctx.fillRect(78,y+116,7,118);ctx.fillStyle=ink;ctx.font='700 18px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(`${confirmed.length} CONFIRMED DONATION${confirmed.length===1?'':'S'}`,108,y+158);ctx.fillStyle=muted;ctx.font='500 18px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(Object.keys(totals).length?Object.entries(totals).map(([c,n])=>money(n,c)).join('  ·  '):'No confirmed donations in this period',108,y+196);y+=290}ctx.fillStyle=ink;ctx.font='700 22px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('Donation history',78,y);y+=42;ctx.fillStyle='#f1f5f9';ctx.fillRect(78,y,1084,48);ctx.fillStyle=muted;ctx.font='700 14px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('DATE',94,y+31);ctx.fillText('REFERENCE',240,y+31);ctx.fillText('COUNTRY',480,y+31);ctx.fillText('METHOD',670,y+31);ctx.fillText('STATUS',900,y+31);ctx.textAlign='right';ctx.fillText('AMOUNT',1146,y+31);ctx.textAlign='left';y+=48;const pageRows=rows.slice(pageIndex*perPage,(pageIndex+1)*perPage);if(!pageRows.length){ctx.fillStyle=muted;ctx.font='400 20px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('No donations were recorded during this period.',94,y+52)}for(const g of pageRows){ctx.fillStyle=ink;ctx.font='500 16px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText(date(g.date),94,y+38);ctx.fillText(donationRef(g.id).slice(0,22),240,y+38);ctx.fillText(countryName(g.country).slice(0,18),480,y+38);ctx.fillText(String(g.method).slice(0,20),670,y+38);ctx.fillStyle=g.status==='received'?'#18794e':g.status==='pending'?'#9a6700':'#b42318';ctx.fillText(g.status[0].toUpperCase()+g.status.slice(1),900,y+38);ctx.fillStyle=ink;ctx.textAlign='right';ctx.fillText(`${g.currency} ${Number(g.amount).toLocaleString('en',{maximumFractionDigits:2})}`,1146,y+38);ctx.textAlign='left';ctx.strokeStyle=line;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(78,y+64);ctx.lineTo(1162,y+64);ctx.stroke();y+=76}ctx.fillStyle=orange;ctx.fillRect(78,1542,1084,4);ctx.fillStyle=ink;ctx.font='700 21px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('BENMP Global Giving Platform',78,1594);ctx.fillStyle=muted;ctx.font='400 15px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';ctx.fillText('Confirmed donations are included in totals.',78,1628);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.92));images.push(new Uint8Array(await blob.arrayBuffer()))}return jpegPagesPDF(images,width,height)}
async function downloadStatement(period){toast('Preparing your giving statement…');try{download(`BENMP-giving-statement-${period}.pdf`,await statementPDF(period),'application/pdf');toast('Giving statement downloaded')}catch{toast('Could not prepare the statement. Please try again.')}}
async function emailStatement(period,email){toast('Preparing your giving statement…');try{await statementPDF(period);const label=statementWindow(period).label;message('Your BENMP giving statement',`Your giving statement for ${label} was generated for ${email}.`,'Email',{attachment:'BENMP giving statement.pdf',statementPeriod:period});save();toast(`Giving statement emailed to ${email}`)}catch{toast('Could not prepare the statement. Please try again.')}}
async function receipt(id){const g=db.gifts.find(x=>x.id===id);if(!g||g.status!=='received')return;toast('Preparing receipt PDF…');try{download(`BENMP-${donationRef(g.id)}-receipt.pdf`,await receiptPDF(g),'application/pdf');toast('Receipt PDF downloaded')}catch{toast('Could not prepare the receipt. Please try again.')}}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportCSV(){const rows=[['Reference','Date','Partner','Email','Kind','Country','Currency','Amount','Status','Method'],...db.gifts.map(g=>[donationRef(g.id),g.date,g.org||g.name,g.email,g.kind,countryName(g.country),g.currency,g.amount,g.status,g.method])];download('BENMP-giving-history.csv',rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv');toast('Giving history exported')}
function confirmGift(id){const g=db.gifts.find(x=>x.id===id);if(!g||g.status!=='pending')return;g.status='received';const p=db.plans.find(p=>p.id===g.plan);if(p&&p.status==='Awaiting payment')p.status='Active';emitNotice('Your donation is confirmed',`Your ${money(g.amount,g.currency)} donation is now received. Reference ${g.id}.`);save();render();toast('Payment confirmed')}
function retry(id){const g=db.gifts.find(x=>x.id===id);if(!g)return;draft={...fresh(),amount:String(g.amount),currency:g.currency,country:g.country,kind:g.kind,name:g.name,email:g.email,org:g.org,orgEmail:g.email,method:g.methodId,frequency:g.frequency,identity:'id',outcome:'received'};step=3;go('give')}
function editPlan(id){const p=db.plans.find(x=>x.id===id);if(!p||p.status==='Canceled')return;modal('Edit monthly partnership',`<form id="plan-form" data-id="${p.id}">${field('Amount ('+p.currency+')','plan-amount',p.amount,'number','min="0.01" step="any" required')}${select('Monthly date','plan-day',Array.from({length:28},(_,i)=>String(i+1)),String(p.day))}${select('Payment method','plan-method',[['card','Debit / credit card'],['debit','Bank debit'],['paypal','PayPal'],['momo','Mobile Money — reminder'],['wire','Bank wire — reminder']],p.methodId)}<p class="hint">Applies to the next unprocessed installment. No extra donation is charged now.</p><button class="primary full" type="submit">Save changes</button></form>`)}
function planStatus(id,status){const p=db.plans.find(x=>x.id===id);if(!p||p.status==='Canceled')return;p.status=status;if(status==='Active')p.next=nextDate(p.day);emitNotice('Monthly partnership '+status.toLowerCase(),`${money(p.amount,p.currency)} plan is now ${status.toLowerCase()}. ${status==='Active'?'Next date: '+date(p.next)+'. No missed months will be collected.':'Future collection is stopped.'}`);save();close();render();toast('Plan '+status.toLowerCase())}
function runPlan(id){const p=db.plans.find(x=>x.id===id);if(!p||p.status!=='Active')return;if(p.mode==='Reminder'){message('Your monthly partnership reminder',`It’s time for your ${money(p.amount,p.currency)} donation. Choose Give to approve a new payment. No automatic debit was made.`);p.next=nextDate(p.day);save();render();toast('Reminder added to inbox');return}const g={...p,id:uid('DONATION'),plan:p.id,frequency:'monthly',status:'received',date:p.next};delete g.next;db.gifts.unshift(g);const n=new Date(p.next);n.setMonth(n.getMonth()+1,Math.min(28,p.day));p.next=n.toISOString();emitNotice('Monthly donation received',`Your monthly ${money(p.amount,p.currency)} donation was received. Reference ${g.id}.`);save();render();toast('Monthly payment received')}
function seed(){if(db.gifts.some(g=>g.imported)){toast('Giving activity is already loaded');return}for(const [i,c]of ['GH','US','GB','KE','ZA','CA'].entries()){const d=new Date();d.setMonth(d.getMonth()-(i%3));db.gifts.push({id:uid('DONATION'),amount:[1000,100,75,5000,500,150][i],currency:currencyMap[c],country:c,kind:i===4?'organization':'individual',org:i===4?'Grace Outreach Church':'',name:'Joshua GBAFA',email:i===4?'finance@example.com':'joshua@example.com',method:i%2?'Debit / credit card':'Mobile Money',methodId:i%2?'card':'momo',frequency:'once',status:'received',date:d.toISOString(),imported:true})}message('A view of your partnership','Your recent donations are ready to view.','In-app');save();render();toast('Giving activity loaded')}
function render(){view=location.hash.slice(1)||'home';if(!db.session&&(view==='dashboard'||view==='messages')){view='home';history.replaceState(null,'','#home');home();return}if(view==='give')giving();else if(view==='dashboard')dashboard();else if(view==='messages')messagesUI();else if(view==='result')result();else home()}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
document.addEventListener('input',e=>{if(e.target.dataset.phoneCountry){capture();const match=phoneCountrySearchMatch(e.target.value);if(match){draft.phoneCountry=match.code;giving()}return}if(e.target.id==='country-search'){const match=countrySearchMatch(e.target.value);if(match){setCountry(match.code);giving()}return}if(e.target.closest('#giving-form')){capture();if(e.target.name==='amount'){const el=$('#summary-amount');if(el)el.textContent=draft.amount?Number(draft.amount).toLocaleString('en',{maximumFractionDigits:2}):'—';document.querySelectorAll('[data-amount]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.amount)===Number(draft.amount)))}}if(e.target.id==='history-search'){filter=e.target.value;const list=db.gifts.filter(g=>(statusFilter==='all'||g.status===statusFilter)&&[g.id,g.name,g.org,g.email,g.method].join(' ').toLowerCase().includes(filter.toLowerCase()));$('#gift-list').innerHTML=giftRows(list)}});
document.addEventListener('change',e=>{if(e.target.closest('#giving-form')){capture();if(e.target.name==='country'){setCountry(e.target.value);giving()}else if(e.target.name==='currency')giving()}if(e.target.id==='status-filter'){statusFilter=e.target.value;dashboard()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='statement-form'){const period=$('#statement-period').value,email=$('#statement-email').value.trim(),action=e.submitter?.value||'download';if(action==='email'){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter a valid email address');return}await emailStatement(period,email)}else await downloadStatement(period);return}if(f.id==='giving-form'){capture();const error=validate();if(error){$('#form-error').innerHTML=`<p class="error">${esc(error)}</p>`;$('#form-error').scrollIntoView({block:'nearest'});return}if(step<3){step++;giving();window.scrollTo(0,0)}else completeGift()}if(f.id==='login-form'){const entry=$('#login-entry').value.trim();if(!entry)return;modal('Your sign-in link is ready',`<p>A secure sign-in link has been sent to your BENMP ID.</p><div class="notice">Account: <strong>Joshua GBAFA</strong><br>BENMP ID: joshua@example.com</div>${button('Open secure sign-in link','finish-login','primary full',`data-entry="${esc(entry)}"`)}`)}if(f.id==='profile-form'){db.profile={name:$('#profile-name').value||'Joshua GBAFA',email:$('#profile-email').value,phone:$('#profile-phone').value};save();toast('Saved details updated');render()}if(f.id==='prefs-form'){for(const k of Object.keys(db.prefs))db.prefs[k]=!!f.elements[k].checked;save();close();toast('Notification preferences saved')}if(f.id==='plan-form'){const p=db.plans.find(x=>x.id===f.dataset.id),amount=Number($('#plan-amount').value);if(!p||!Number.isFinite(amount)||amount<=0)return;p.amount=amount;p.day=Number($('#plan-day').value);p.next=nextDate(p.day);p.methodId=$('#plan-method').value;p.method=$('#plan-method').selectedOptions[0].textContent;p.mode=isAuto(p.methodId)?'Automatic':'Reminder';emitNotice('Your monthly plan was updated',`${money(p.amount,p.currency)} on day ${p.day}. Changes apply to the next installment.`);save();close();render();toast('Monthly plan updated')}if(f.id==='compose-form'){message($('#message-subject').value,$('#message-body').value,$('#message-channel').value);save();close();go('messages');toast('Message saved')}if(f.id==='reply-form'){message('Your reply',$('#reply-body').value,'In-app');save();close();render();toast('Reply saved')}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if('copy' in b.dataset){copyValue(b.dataset.copy,b.dataset.copyLabel||'Value');return}if(b.dataset.action==='statement-attachment'){downloadStatement(b.dataset.period||'all');return}if(b.dataset.set){capture();draft[b.dataset.set]=b.dataset.value;giving();return}if(b.dataset.amount){draft.amount=b.dataset.amount;giving();return}if(b.dataset.step){capture();step=Number(b.dataset.step);giving();return}if(b.dataset.identity){capture();draft.identity=b.dataset.identity;giving();return}if(b.dataset.method){capture();draft.method=b.dataset.method;draft.network=selectedMethod()[3]?.[0]||'';draft.mandate=false;giving();return}if(b.dataset.network){draft.network=b.dataset.network;giving();return}if(b.dataset.tab){dashTab=b.dataset.tab;dashboard();return}if(b.dataset.action==='apple-pay'){capture();const error=validate();if(error){const box=$('#form-error');if(box)box.innerHTML=`<p class="error">${esc(error)}</p>`;return}completeGift();return}const a=b.dataset.action,id=b.dataset.id;if(b.id==='signin'){if(db.session){dashTab='profile';go('dashboard')}else login();return}if(b.id==='appearance'){modal('Make yourself at home',`<p>Choose an appearance and the level of simplicity you prefer.</p><div class="actions">${button('Light','light','secondary')}${button('Dark','dark','secondary')}</div><div class="notice">${db.simple?'Extra-simple mode is on.':'Standard mode is on.'}</div>${button(db.simple?'Switch to standard':'Try extra-simple mode','simple','primary full')}`);return}if(a==='start')start();if(a==='partner')start(true);if(a==='partner-current'){capture();draft.partner=true;draft.frequency='monthly';giving()}if(a==='back'){capture();step=Math.max(1,step-1);giving()}if(a==='dashboard')go('dashboard');if(a==='login')login();if(a==='finish-login')finishLogin(b.dataset.entry);if(a==='close')close();if(a==='logout'){db.session=null;save();toast('Signed out');if(view==='dashboard'||view==='messages')go('home');else render()}if(a==='profile'){dashTab='profile';go('dashboard')}if(a==='receipt')receipt(id);if(a==='export')exportCSV();if(a==='confirm-gift')confirmGift(id);if(a==='retry')retry(id);if(a==='preferences')preferences();if(a==='read-all'){db.messages.forEach(m=>m.read=true);save();render()}if(a==='read-message'){const m=db.messages.find(x=>x.id===id);if(m)m.read=true;save();render()}if(a==='welcome'){message('Welcome, Joshua GBAFA','Thank you for partnering with BENMP. Your email is your BENMP ID. Explore your giving and monthly partnership in My giving.');save();render()}if(a==='compose'){modal('Compose message',`<form id="compose-form">${select('Channel','message-channel',['Email','WhatsApp','SMS','In-app'],'Email')}${field('Subject','message-subject','A note from BENMP','text','required')}<label class="label" for="message-body">Message</label><textarea class="field" id="message-body" rows="4" required>Thank you for partnering with us.</textarea><button type="submit" class="primary full">Save message</button><p class="hint">Your message will be saved to the BENMP inbox.</p></form>`)}if(a==='reply')modal('Reply',`<form id="reply-form"><label class="label" for="reply-body">Your reply</label><textarea class="field" id="reply-body" rows="4" required></textarea><button class="primary full" type="submit">Save reply</button></form>`);if(a==='edit-plan')editPlan(id);if(a==='pause-plan')planStatus(id,'Paused');if(a==='resume-plan')planStatus(id,'Active');if(a==='run-plan')runPlan(id);if(a==='cancel-plan')modal('Cancel this monthly partnership?',`<p>This stops future collections and reminders. Previous donations remain in your history.</p><div class="actions">${button('Keep plan','close','secondary')}${button('Cancel monthly plan','confirm-cancel','primary',`data-id="${id}"`)}</div>`);if(a==='confirm-cancel')planStatus(id,'Canceled');if(a==='seed')seed();if(a==='light'||a==='dark'){db.theme=a;save();applyTheme();close()}if(a==='simple'){db.simple=!db.simple;save();applyTheme();close()}if(a==='privacy')modal('Your privacy','<p>Your details, donations, preferences and messages are protected. You can clear saved information from this browser at any time.</p><p style="margin-top:15px">BENMP protects access to your giving information and account.</p>');if(a==='help')modal('Explore BENMP',`<p>Choose Give for a one-time donation, or Become a BENMP partner for a monthly commitment. Pick any country and amount, then try saved details, email-only giving or a first-time donation.</p><p style="margin-top:15px">Switch payment methods, download receipts, manage plans and export your giving activity. Messages keeps your notifications together.</p>`);if(a==='reset')modal('Reset your data?',`<p>Remove all donations, plans, messages and saved preferences from this browser?</p><div class="actions">${button('Keep my data','close','secondary')}${button('Reset','confirm-reset','primary')}</div>`);if(a==='confirm-reset'){db=blank();draft=fresh();step=1;save();close();go('home');render();toast('Data reset')}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
applyTheme();render();
