if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [{name:'read_giving_activity',description:'Read the current BENMP view and aggregate giving activity. No personal details returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {view,step,gifts:db.gifts.length,plans:db.plans.length,country:draft.country,currency:draft.currency,amount:draft.amount}}},{name:'configure_donation',description:'Stage a BENMP donation without submitting it.',inputSchema:{type:'object',properties:{country:{type:'string'},amount:{type:'number',exclusiveMinimum:0},monthly:{type:'boolean'}},required:['country','amount'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!codes.includes(input.country)||restricted.has(input.country)||!Number.isFinite(input.amount)||input.amount<=0)throw new Error('Choose a valid country and positive amount.');start(!!input.monthly);setCountry(input.country);draft.amount=String(input.amount);giving();return {staged:true,country:draft.country,amount:draft.amount,currency:draft.currency}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}}
